    grid = [list(row) for row in grid]
    if not grid or not grid[0]:
        return grid
    h, w = len(grid), len(grid[0])
    full_rows = {r: grid[r][0] for r in range(h) if all(v == grid[r][0] for v in grid[r])}
    full_cols = {c: grid[0][c] for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))}
    shared = set(full_rows.values()) & set(full_cols.values())
    if not shared:
        return grid
    separator = max(shared, key=lambda color: sum(v == color for v in full_rows.values()) + sum(v == color for v in full_cols.values()))
    row_cuts = [r for r, color in full_rows.items() if color == separator]
    col_cuts = [c for c, color in full_cols.items() if color == separator]
    row_spans = []
    start = 0
    for cut in row_cuts:
        if start < cut:
            row_spans.append((start, cut))
        start = cut + 1
    if start < h:
        row_spans.append((start, h))
    col_spans = []
    start = 0
    for cut in col_cuts:
        if start < cut:
            col_spans.append((start, cut))
        start = cut + 1
    if start < w:
        col_spans.append((start, w))
    if not row_spans or not col_spans:
        return grid
    cells = [grid[r][c] for r0, r1 in row_spans for c0, c1 in col_spans for r in range(r0, r1) for c in range(c0, c1)]
    background = max(set(cells), key=cells.count)
    tiles = []
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            tile = [row[c0:c1] for row in grid[r0:r1]]
            score = sum(v != background for row in tile for v in row)
            tiles.append((score, r0, r1, c0, c1, tile))
    _, sr0, sr1, sc0, sc1, source = max(tiles, key=lambda item: item[0])
    sh, sw = len(source), len(source[0])
    for _, r0, r1, c0, c1, _ in tiles:
        if r1 - r0 == sh and c1 - c0 == sw:
            for dr in range(sh):
                grid[r0 + dr][c0:c1] = source[dr][:]
    return grid
